import ErrorCode from './ErrorCode.js';
export class IdNotMatchException extends Error {
  constructor(requestId, responseId) {
    super("Expect json rpc id to be ".concat(requestId, ", but ").concat(responseId, " received"));
    this.code = ErrorCode.IdNotMatch;
  }
}
export class ResponseException extends Error {
  constructor() {
    super(...arguments);
    this.code = ErrorCode.ResponseMessage;
  }
}
export default {
  IdNotMatchException,
  ResponseException
